    'act_wh_count' => ['what' => 'Record stock count quantities.', 'data' => 'Counted quantities on a count sheet.'],
    'act_wh_count_manage' => ['what' => 'Open, approve and cancel stock counts.', 'data' => 'Opening snapshots a warehouse; approval adjusts system stock to the counted quantities.'],
    'act_wh_pick' => ['what' => 'Start picking, edit picked quantities and mark orders ready.', 'data' => 'Pick status and picked quantities.'],
    'act_wh_pick_raise' => ['what' => 'Raise a pick from an order or request, and cancel picks.', 'data' => 'Creates or cancels warehouse pick orders.'],
    'act_warehouses_manage' => ['what' => 'Create and edit warehouses and set opening stock per product.', 'data' => 'Warehouse records, and stock and hold quantities written directly (not through a count).'],
    'act_custody_handout' => ['what' => 'Load van stock to reps.', 'data' => 'Moves stock from warehouse to a rep van.'],
    'act_custody_adjust' => ['what' => 'Correct the loaded and gift quantities of a rep van custody; a reason is required.', 'data' => 'Rewrites the quantities in the custody ledger only, which changes the rep settlement figures and notifies the rep. The floor is sold + returned + transferred. Warehouse stock and shelves are not touched.'],
    'act_ka_create' => ['what' => 'Create, assign, reassign, cancel and import sales orders.', 'data' => 'Creates orders; assigning notifies the rep; reassign moves the order to another client; cancelling can return goods to the warehouse.'],
    'act_ka_decide' => ['what' => 'Approve or reject pending sales orders, one by one or in bulk.', 'data' => 'Approval raises a warehouse pick for the order (a rep and a warehouse are needed) and can edit quantities; rejection notifies the creator.'],
    'act_ka_edit' => ['what' => 'Edit a sales order before it is decided.', 'data' => 'Order lines, quantities, client, rep and warehouse of a pending order.'],
    'act_field_plan' => ['what' => 'Assign clients to reps and plan journeys: assign, unassign, reorder, copy, auto-assign, zones.', 'data' => 'Client-to-rep assignments, rep zones and journey plan rows, limited to the scope of the user.'],
    'act_field_wipe' => ['what' => 'Wipe journey plans.', 'data' => 'An admin wipes every journey plan; any other holder wipes only the plans of his team and his own. Visits are not touched.'],
    'act_field_decide' => ['what' => 'Decide new-client requests, manage refill requests and close a rep van custody.', 'data' => 'Approving a request creates the client and notifies the rep; refill assign raises a pick; closing marks the current van custody of the rep as closed (the rep himself is not affected).'],
    'act_suppliers_manage' => ['what' => 'Add and edit suppliers and set their opening balance.', 'data' => 'Supplier data; the opening balance replaces the supplier opening entry (refused in closed periods).'],
