    'act_purchasing_manage' => ['what' => 'Create, invoice, cancel and close supplier purchase orders.', 'data' => 'Orders that break the approval rules wait for approval (an admin order is approved at once); invoicing records a supplier invoice for received goods; cancelling is refused once goods are received.'],
    'act_supplier_contracts_manage' => ['what' => 'Create and edit supplier contracts.', 'data' => 'Contract terms and agreed items.'],
    'act_purchasing_approve' => ['what' => 'Approve or reject pending purchase orders.', 'data' => 'Purchase order approval.'],
    'act_purchase_requests_create' => ['what' => 'Raise and cancel purchase requests.', 'data' => 'Purchase requests.'],
    'act_purchase_requests_quote' => ['what' => 'Add supplier quotes to a request.', 'data' => 'Quotes and prices.'],
