    'act_money_dues' => ['what' => 'Generate dues from contracts, settle them and waive them.', 'data' => 'Generate creates due rows; settling posts a rebate credit on the client statement; waiving cancels the due with a note. Closed periods are refused.'],
    'act_money_eta' => ['what' => 'Export invoices for e-invoicing, mark them submitted and save tax settings.', 'data' => 'Export flags the ready invoices as exported; mark-submitted flags exported ones as submitted; saving changes the tax rate and the company and bank details used on documents.'],
    'act_gl_post' => ['what' => 'Post and void expenses, cash movements and manual entries; override entry accounts; edit accounts, safes, safe counts, bank reconciliation, fixed assets; close periods.', 'data' => 'Creates and voids ledger entries, pays expenses, and closing a period blocks further changes to it.'],
    'act_gl_expense_approve' => ['what' => 'Approve or reject expenses.', 'data' => 'Expense approval status; a rejection needs a note.'],
    'act_gl_admin' => ['what' => 'Posting rules, account mapping, GL start date, reopen periods, rebuild entries, adopt the chart of accounts, go-live wizard, expense categories and monthly depreciation.', 'data' => 'Changes how and when the whole ledger is posted; moving the start date later purges entries before it; a rebuild rewrites entries.'],
    'act_costing_admin' => ['what' => 'Close costing months, recompute and post costs from a date, and approve transfer prices.', 'data' => 'Closing finishes a costing month; sync recomputes the cost layer and posts it; approving sets the transfer price of a product.'],
