    'act_org_manage' => ['what' => 'Edit zones and quick-create chains and zones from forms.', 'data' => 'Zones and quick chain records; a zone with active clients cannot be deactivated.'],
    'act_org_structure' => ['what' => 'Edit governorates, branches, vehicles (with driver), chains, mother companies and channels.', 'data' => 'Company structure; chain edits can push tax, documents and commercial register to every branch; attaching branches to a chain with pricing defaults creates a draft price change.'],
