    'act_mfg_qc_decide' => ['what' => 'Release or reject a production batch.', 'data' => 'Whether a batch can be sold.'],
    'act_hr_employees' => ['what' => 'Add and edit employee files.', 'data' => 'Employee personal and job data.'],
    'act_hr_leave_balances' => ['what' => 'Edit leave balances and seed opening balances for a year.', 'data' => 'Leave days per employee; seeding creates opening balances for the chosen year.'],
