    'act_clients_delete' => ['what' => 'Permanently delete a client with no related records, and purge visits that carry no money or documents.', 'data' => 'Refused if the client has any invoices, collections or other records; the purge keeps visits tied to money or documents.'],
    'act_clients_geo' => ['what' => 'Set a client\'s governorate and zone from activation.', 'data' => 'Client geography.'],
