    'act_field_gps' => ['what' => 'Set up and sync vehicle GPS trackers.', 'data' => 'Tracker credentials and sync.'],
    'act_custody_clear' => ['what' => 'Clear a rep whole custody, in one of two modes.', 'data' => 'Return mode zeroes the remaining van quantities through the custody ledger adjustment (reason needed, rep notified, warehouse untouched); wipe mode rewrites the ledger directly and is for test data only.'],
    'act_wh_fix_qty' => ['what' => 'Fix the received quantity of a batch.', 'data' => 'Rewrites the received quantity (cannot go below what was issued or damaged) and trims shelf quantities to match.'],
    'act_ka_reprice' => ['what' => 'Reprice open sales orders to the current price list: one, bulk, or via the check screen.', 'data' => 'Rewrites prices and totals of sales orders that are not delivered or cancelled.'],
    'act_invoices_edit' => ['what' => 'Correct invoices: renumber all, edit items, switch cash or credit, reassign client, change date, reprice, set paper ref.', 'data' => 'Changes posted invoices: item edits move the rep van stock, renumbering rewrites invoice numbers in open periods, and each change reposts the ledger entries and recalculates the client balance. Exported e-invoices in closed periods are refused.'],
