    'act_repclose_close' => ['what' => 'Close a rep settlement: cash received against expected, optionally closing the van custody.', 'data' => 'Records the settlement with the received cash and carries any balance; can close the current custody.'],
    'act_repclose_delete' => ['what' => 'Delete a rep\'s latest settlement.', 'data' => 'Reopens the rep\'s position.'],
    'act_dayclose_close' => ['what' => 'Save the figures of a day as the day close.', 'data' => 'Stores the totals of that date; one close per date.'],
    'act_gl_coa_draft' => ['what' => 'Edit the chart of accounts draft.', 'data' => 'Draft accounts only.'],
    'act_online_sync' => ['what' => 'Run the online sync.', 'data' => 'Imports online orders.'],
    'act_online_sync_settings' => ['what' => 'Save the online store sync settings and reset test data.', 'data' => 'Reset restocks orders that took stock out, deletes ALL online orders, pickups and online picks, and clears the status in the store.'],
    'act_online_prep' => ['what' => 'Start, review and finish online order preparation.', 'data' => 'Pick status; finishing marks the order ready and pushes its status to the store.'],
    'act_online_orders' => ['what' => 'Online order decisions: confirm, ship, cancel, postpone, reship, return, relink, pickup push.', 'data' => 'Confirm raises a pick; shipping creates a pickup and fulfils the order in the store; cancel restocks and cancels in the store; return takes the returned pieces back into stock.'],
    'act_online_manual_ship' => ['what' => 'Ship an online order manually and record its collection.', 'data' => 'Marks it shipped and records the collected amount, pickup and a zero cost; stock is deducted (first-expiry batches) only if the deduct box is ticked while the order is in preparation.'],
    'act_online_collect' => ['what' => 'Record cash collected on a shipped online order.', 'data' => 'Adds to the collected total; completing it marks the order paid in the store; collecting more than is owed is refused.'],
    'act_online_products' => ['what' => 'Link online products to catalogue products and bundles.', 'data' => 'Product links and bundles; a change updates the SKU in the store and the items of orders not yet confirmed.'],
    'act_targets_edit' => ['what' => 'Save and copy monthly targets.', 'data' => 'Monthly targets.'],
    'act_targets_annual' => ['what' => 'Split annual targets to reps and clients.', 'data' => 'Rep and client annual targets.'],
    'act_targets_annual_company' => ['what' => 'Set company and manager annual targets and edit manually.', 'data' => 'Top-level targets that drive the whole split.'],
