    'act_incentives_manage' => ['what' => 'Save incentive settings and replace the commission tiers.', 'data' => 'The points rate and the commission tier table (old tiers are deleted and rewritten).'],
    'act_attendance_approve' => ['what' => 'Approve attendance hours.', 'data' => 'Approved hours that feed payroll.'],
    'act_hr_supervisor_punch' => ['what' => 'Punch for the supervisor\'s workers.', 'data' => 'Attendance punches of his team.'],
    'act_hr_leave_decide' => ['what' => 'Approve or reject team leave and hourly permissions.', 'data' => 'Leave and permission decisions.'],
    'act_hr_fingerprint' => ['what' => 'Manage fingerprint devices: add, edit, queue commands, map employee PINs, settings.', 'data' => 'Device setup and the PIN mapping of employees; mapping re-applies old punches of that PIN.'],
    'act_app_version_manage' => ['what' => 'Upload the app APK and set the latest and minimum app version.', 'data' => 'Replaces the APK served to every device and sets the version rules; a minimum above the latest is refused.'],
